private CategoryDataset dataset;
private CategoryAxis domainAxis;
private ValueAxis rangeAxis;
private CategoryItemRenderer renderer;
private Marker marker;
private Layer layer;
private Map foregroundRangeMarkers;
private Map backgroundRangeMarkers;

@Before
public void setUp() throws Exception {
    plot = new CategoryPlot();
    dataset = DatasetUtilities.createCategoryDataset("Series 1", new String[] {"A", "B", "C"}, new double[][] {{1.0, 2.0, 3.0}});
    domainAxis = new CategoryAxis("Domain");
    rangeAxis = new ValueAxis("Range");
    renderer = new CategoryItemRenderer();
    plot.setDataset(dataset);
    plot.setDomainAxis(domainAxis);
    plot.setRangeAxis(rangeAxis);
    plot.setRenderer(renderer);
    foregroundRangeMarkers = new HashMap();
    backgroundRangeMarkers = new HashMap();
    plot.setForegroundRangeMarkers(foregroundRangeMarkers);
    plot.setBackgroundRangeMarkers(backgroundRangeMarkers);
}

@Test
public void testRemoveRangeMarker() {
    // Add a marker to the foreground layer
    marker = new ValueMarker(0.0, Color.blue, BasicStroke.SINGLE_LINE, Color.red, BasicStroke.SINGLE_LINE, 0.5f);
    plot.addRangeMarker(marker, Layer.FOREGROUND);
    // Remove the marker and check if it is removed
    boolean removed = plot.removeRangeMarker(marker, Layer.FOREGROUND);
    Assert.assertTrue("Marker should be removed", removed);
    // Check if the marker is not in the foreground layer anymore
    Assert.assertFalse("Marker should not be in the foreground layer", foregroundRangeMarkers.containsValue(marker));
    // Check if the marker is still in the background layer
    Assert.assertFalse("Marker should not be in the background layer", backgroundRangeMarkers.containsValue(marker));
}

