@Before
public void setUp() throws Exception {
    keyedValues = new DefaultKeyedValues();
    keys = new ArrayList<>();
    values = new ArrayList<>();
    indexMap = new HashMap<>();
}

@Test
public void testRemoveValueWhenListIsEmpty() {
    // Test removing from empty list
    Assert.assertThrows(IndexOutOfBoundsException.class, () -> keyedValues.removeValue(0));
}

@Test
public void testRemoveValueValidIndex() {
    // Add some values
    keyedValues.addValue("A", 1.0);
    keyedValues.addValue("B", 2.0);
    keyedValues.addValue("C", 3.0);
    // Remove index 1
    keyedValues.removeValue(1);
    // Check that the key and value at index 1 are removed
    Assert.assertEquals("A", keyedValues.getKey(0));
    Assert.assertEquals(1.0, keyedValues.getValue(0), 0.01);
    Assert.assertEquals("C", keyedValues.getKey(2));
    Assert.assertEquals(3.0, keyedValues.getValue(2), 0.01);
    // Check that the indexMap is updated
    Assert.assertEquals(2, keyedValues.getItemCount());
    // Check that the index for key "B" is removed
    Assert.assertFalse(keyedValues.indexMap.containsKey("B"));
}

@Test
public void testRemoveValueIndexOutOfBoundsHigh() {
    // Add two values
    keyedValues.addValue("A", 1.0);
    keyedValues.addValue("B", 2.0);
    // Try to remove index 2 which is out of bounds
    Assert.assertThrows(IndexOutOfBoundsException.class, () -> keyedValues.removeValue(2));
}

@Test
public void testRemoveValueIndexOutOfBoundsLow() {
    // Add two values
    keyedValues.addValue("A", 1.0);
    keyedValues.addValue("B", 2.0);
